from pathlib import Path

js_path=Path("/srv/atlas/static/assets/atlas-v10.js")
css_path=Path("/srv/atlas/static/assets/atlas-v10.css")
js=js_path.read_text()
old_module='function moduleCard(item,{index=0,feature=false}={}){const site=owner(item),selected=state.compare.includes(item.id);return `<article class="module-tile ${feature?\'module-tile--feature\':\'\'}">\n  <div class="module-picture"><a href="${moduleHref(item.id)}" data-link="${moduleHref(item.id)}" aria-label="Study ${escapeHTML(item.title)}">${capture(item,{priority:index<5})}</a><div class="module-picture-actions">${saveBtn(item)}<button class="module-compare ${selected?\'selected\':\'\'}" data-compare="${escapeHTML(item.id)}" aria-pressed="${selected}" aria-label="${selected?\'Remove from\':\'Add to\'} comparison: ${escapeHTML(item.title)}">${svg(selected?\'check\':\'plus\')}<span>${selected?\'Selected\':\'Compare\'}</span></button></div></div>\n  <div class="module-tile-content"><span class="mini-meta">${escapeHTML(item.category)} <span>·</span> ${escapeHTML(site?.name||\'Source\')}</span><a class="module-title" href="${moduleHref(item.id)}" data-link="${moduleHref(item.id)}">${escapeHTML(item.title)}</a><p>${escapeHTML(item.lesson)}</p></div>\n  </article>`}\n'
new_module='function moduleCard(item,{index=0,feature=false}={}){const site=owner(item),selected=state.compare.includes(item.id),siteDomain=site?domain(site):\'\';return `<article class="module-tile module-card ${feature?\'module-tile--feature\':\'\'}">\n  <div class="module-picture module-card-media"><a href="${moduleHref(item.id)}" data-link="${moduleHref(item.id)}" aria-label="Study ${escapeHTML(item.title)}">${capture(item,{priority:index<5})}</a><span class="module-card-type">${escapeHTML(item.category)}</span><div class="module-card-actions">${saveBtn(item)}</div></div>\n  <div class="module-tile-content module-card-body">\n    <div class="module-card-kicker"><span class="notranslate" translate="no">${escapeHTML(site?.name||\'Source\')}</span><span>·</span><span>${escapeHTML(siteDomain)}</span></div>\n    <a class="module-title" href="${moduleHref(item.id)}" data-link="${moduleHref(item.id)}">${escapeHTML(item.title)}</a>\n    <p>${escapeHTML(item.lesson)}</p>\n    <div class="module-card-footer"><a href="${escapeHTML(item.url)}" target="_blank" rel="noopener noreferrer" class="module-source-link">Source ${svg(\'arrow\')}</a><button class="module-compare ${selected?\'selected\':\'\'}" data-compare="${escapeHTML(item.id)}" aria-pressed="${selected}" aria-label="${selected?\'Remove from\':\'Add to\'} comparison: ${escapeHTML(item.title)}">${svg(selected?\'check\':\'plus\')}<span>${selected?\'Selected\':\'Compare\'}</span></button></div>\n  </div>\n  </article>`}\n'
old_patterns='function patterns(){const patterns=[[\'Split systems\',\'Different hierarchy, intentional contrast.\',\'fictiv-capability-hero\'],[\'Technical detail\',\'Specifications, trust signals and clear paths.\',\'protolabs-service-grid\'],[\'Product storytelling\',\'Help visitors understand complex offers.\',\'formlabs-applications-hero\'],[\'Project proof\',\'Let documented outcomes establish credibility.\',\'gensler-project-gallery\']];return `<div class="wrap secondary-page"><div class="overline">DESIGN PATTERNS</div><h1>Ways of thinking<br>about layout.</h1><p>Learn from real websites instead of copying a template. These notes are starting points for your own design decisions.</p><div class="pattern-wall">${patterns.map(x=>{const item=state.modules.find(z=>z.id===x[2])||state.modules[0];return `<a class="pattern-sample" href="${moduleHref(item.id)}" data-link="${moduleHref(item.id)}"><div>${capture(item)}</div><h2>${escapeHTML(x[0])} ${svg(\'arrow\')}</h2><p>${escapeHTML(x[1])}</p></a>`}).join(\'\')}</div></div>`}\nfunction empty(title,body,route){return `<div class="empty-board"><div class="empty-symbol">${svg(\'bookmark\')}</div><h2>${escapeHTML(title)}</h2><p>${escapeHTML(body)}</p><a href="${route}" data-link="${route}">Browse references ${svg(\'right\')}</a></div>`}\n'
new_patterns='function patterns(){const patterns=[\n  {name:\'Capability-led hierarchy\',desc:\'Lead with what the buyer can make, verify or source before asking them to explore the company.\',ids:[\'fictiv-capability-hero\',\'hexagon-capability\'],category:\'Capabilities\'},\n  {name:\'Product system\',desc:\'Organize complex product families so visitors can compare categories without reading a catalogue.\',ids:[\'protolabs-service-grid\',\'arburg-product-family\'],category:\'Products\'},\n  {name:\'Process narrative\',desc:\'Turn operational complexity into a sequence with a clear next step and visible handoffs.\',ids:[\'fictiv-process-intro\',\'fictiv-process-stages\'],category:\'Process\'},\n  {name:\'Proof through projects\',desc:\'Use real applications, projects and outcomes as the visual evidence instead of generic trust copy.\',ids:[\'gensler-project-gallery\',\'formlabs-application-story\'],category:\'Projects\'}\n];return `<div class="wrap patterns-page-v15"><header class="patterns-hero-v15"><div><span>PATTERN LIBRARY</span><h1>See the structure<br>behind good B2B pages.</h1></div><p>Each pattern pairs real interface decisions. Compare how different companies solve hierarchy, product discovery, process and proof.</p></header><div class="patterns-grid-v15">${patterns.map((p,i)=>{const items=p.ids.map(id=>state.modules.find(x=>x.id===id)).filter(Boolean);return `<article class="pattern-card-v15"><div class="pattern-card-head-v15"><span>${String(i+1).padStart(2,\'0\')} / ${escapeHTML(p.category)}</span><a href="/sections?category=${encodeURIComponent(p.category)}" data-link="/sections?category=${encodeURIComponent(p.category)}">Explore ${svg(\'arrow\')}</a></div><div class="pattern-pair-v15">${items.map(x=>`<a href="${moduleHref(x.id)}" data-link="${moduleHref(x.id)}" class="pattern-shot-v15">${capture(x)}<span><b>${escapeHTML(owner(x)?.name||\'Source\')}</b><small>${escapeHTML(x.title)}</small></span></a>`).join(\'\')}</div><div class="pattern-copy-v15"><h2>${escapeHTML(p.name)}</h2><p>${escapeHTML(p.desc)}</p></div></article>`}).join(\'\')}</div></div>`}\nfunction empty(title,body,route){return `<div class="empty-board"><div class="empty-symbol">${svg(\'bookmark\')}</div><h2>${escapeHTML(title)}</h2><p>${escapeHTML(body)}</p><a href="${route}" data-link="${route}">Browse references ${svg(\'right\')}</a></div>`}\n'
if old_module not in js:
    raise SystemExit("V1.5 module renderer source not found")
if old_patterns not in js:
    raise SystemExit("V1.5 patterns renderer source not found")
js=js.replace(old_module,new_module).replace(old_patterns,new_patterns)
js_path.write_text(js)
css=css_path.read_text()
overrides='/* V1.5 — tighter gallery rhythm, unified website / section cards, real pattern studies */\n.v13-site-wall,.v13-website-wall,.v13-section-wall{\n  grid-auto-flow:dense;\n  align-items:start;\n}\n/* Websites: the previous layout was not masonry. It used manual nth-child offsets that created dead space. */\n.v13-website-wall{\n  grid-template-columns:repeat(2,minmax(0,1fr));\n  gap:24px 20px;\n}\n.v13-website-wall>.site-tile,\n.v13-website-wall>.site-tile:nth-child(n){\n  grid-column:auto!important;\n  margin-top:0!important;\n}\n.v13-website-wall .site-card{height:auto}\n/* Home keeps variety, but removes artificial vertical gaps. */\n.v13-site-wall{gap:24px 18px}\n.v13-site-wall>.site-tile,.v13-site-wall>.site-tile:nth-child(n){margin-top:0!important}\n.v13-site-wall>.site-tile:nth-child(1){grid-column:span 7}\n.v13-site-wall>.site-tile:nth-child(2){grid-column:span 5}\n.v13-site-wall>.site-tile:nth-child(3){grid-column:span 4}\n.v13-site-wall>.site-tile:nth-child(4){grid-column:span 8}\n.v13-site-wall>.site-tile:nth-child(5),.v13-site-wall>.site-tile:nth-child(6),.v13-site-wall>.site-tile:nth-child(7){grid-column:span 4}\n/* Site card spacing: smaller, calmer, more continuous. */\n.site-card{border-radius:15px;padding:7px 7px 0}\n.site-card .site-image{border-radius:10px}\n.site-card-body{padding:11px 9px 12px;min-height:74px}\n.site-card-kicker{margin-bottom:5px}\n.site-card-focus{margin-top:4px!important}\n.site-tile--featured.site-card{border-radius:16px;padding:7px 7px 0}\n.site-tile--featured.site-card .site-card-body{padding:12px 10px 13px;min-height:78px}\n.site-tile--featured.site-card .tile-name{font-size:16px}\n/* Sections use a complete white-card object rather than floating image + loose text. */\n.v13-section-wall{\n  grid-template-columns:repeat(2,minmax(0,1fr));\n  gap:24px 20px;\n}\n.v13-section-wall>.module-tile,.v13-section-wall>.module-tile:nth-child(n){\n  grid-column:auto!important;\n  margin-top:0!important;\n}\n.module-card{\n  background:#fff;\n  border:1px solid #e8e8ea;\n  border-radius:15px;\n  padding:7px 7px 0;\n  overflow:hidden;\n  box-shadow:0 1px 2px rgba(0,0,0,.025);\n  transition:transform .25s ease,box-shadow .25s ease,border-color .25s ease;\n}\n.module-card:hover{transform:translateY(-3px);border-color:#dcdce0;box-shadow:0 18px 46px rgba(0,0,0,.08)}\n.module-card .module-picture{aspect-ratio:1.58;border:0;border-radius:10px;background:#f4f4f5;box-shadow:none;transform:none!important}\n.module-card:hover .module-picture{box-shadow:none;transform:none!important}\n.module-card:hover .module-picture img{transform:scale(1.012)}\n.module-card-type{position:absolute;left:9px;top:9px;padding:6px 8px;border-radius:999px;background:rgba(255,255,255,.92);backdrop-filter:blur(14px);font-size:8px;font-weight:750;letter-spacing:.04em;color:#444;border:1px solid rgba(0,0,0,.06);z-index:2}\n.module-card-actions{position:absolute;right:9px;top:9px;z-index:3}\n.module-card-actions .shot-save{width:31px;height:31px;border-radius:9px;border-color:rgba(0,0,0,.07);background:rgba(255,255,255,.93);color:#111;box-shadow:0 4px 14px rgba(0,0,0,.06)}\n.module-card-actions .shot-save:hover,.module-card-actions .saved{background:#111!important;color:#fff!important;border-color:#111!important}\n.module-card-body{padding:11px 9px 12px}\n.module-card-kicker{display:flex;gap:6px;align-items:center;color:#929297;font-size:9px;line-height:1.2;margin-bottom:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.module-card-kicker span{overflow:hidden;text-overflow:ellipsis}\n.module-card .module-title{font-size:16px;line-height:1.2;margin:0;text-decoration:none!important;letter-spacing:-.35px}\n.module-card .module-title:hover{opacity:.62}\n.module-card .module-tile-content p{margin:5px 0 11px;font-size:10.5px;line-height:1.45;color:#7d7d82;max-width:none;-webkit-line-clamp:2}\n.module-card-footer{display:flex;align-items:center;justify-content:space-between;gap:10px;padding-top:9px;border-top:1px solid #eeeeef}\n.module-source-link{display:inline-flex;align-items:center;gap:5px;font-size:9.5px;color:#777;font-weight:650}\n.module-source-link .ic{width:12px;height:12px}\n.module-source-link:hover{color:#111}\n.module-card .module-compare{position:static!important;min-height:29px;height:29px;padding:0 9px;border:1px solid #e4e4e6!important;background:#f7f7f8!important;color:#333!important;border-radius:8px;box-shadow:none!important;font-size:9.5px}\n.module-card .module-compare.selected{background:#111!important;color:#fff!important;border-color:#111!important}\n.module-card .module-compare .ic{width:12px;height:12px}\n/* Pattern page: paired real examples, no generic four-card explainer. */\n.patterns-page-v15{padding-top:62px;padding-bottom:110px}\n.patterns-hero-v15{display:grid;grid-template-columns:1.05fr .75fr;gap:70px;align-items:end;padding-bottom:37px;border-bottom:1px solid #e9e9eb}\n.patterns-hero-v15 span{font-size:9px;letter-spacing:.15em;font-weight:800;color:#888}\n.patterns-hero-v15 h1{font-size:clamp(46px,5.2vw,76px);line-height:.98;letter-spacing:-3.8px;margin:10px 0 0}\n.patterns-hero-v15>p{font-size:13px;line-height:1.7;color:#777;max-width:520px;margin:0}\n.patterns-grid-v15{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin-top:26px}\n.pattern-card-v15{background:#fff;border:1px solid #e7e7e9;border-radius:16px;padding:12px;box-shadow:0 1px 2px rgba(0,0,0,.025)}\n.pattern-card-head-v15{display:flex;justify-content:space-between;align-items:center;padding:3px 3px 11px;color:#888;font-size:9px;font-weight:700;letter-spacing:.06em}\n.pattern-card-head-v15 a{display:flex;align-items:center;gap:5px;color:#555;letter-spacing:0}\n.pattern-card-head-v15 a .ic{width:12px;height:12px}\n.pattern-pair-v15{display:grid;grid-template-columns:1.15fr .85fr;gap:7px;align-items:stretch}\n.pattern-shot-v15{position:relative;min-width:0;overflow:hidden;border-radius:11px;background:#f4f4f5;aspect-ratio:1.46}\n.pattern-shot-v15:nth-child(2){aspect-ratio:1.16}\n.pattern-shot-v15 img{width:100%;height:100%;object-fit:cover;object-position:top left;transition:transform .35s ease}\n.pattern-shot-v15:hover img{transform:scale(1.015)}\n.pattern-shot-v15 span{position:absolute;left:8px;right:8px;bottom:8px;padding:8px 9px;border-radius:8px;background:rgba(255,255,255,.92);backdrop-filter:blur(15px);display:block}\n.pattern-shot-v15 b{display:block;font-size:10px;color:#111}\n.pattern-shot-v15 small{display:block;margin-top:2px;color:#777;font-size:8.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.pattern-copy-v15{padding:15px 4px 5px}\n.pattern-copy-v15 h2{font-size:20px;line-height:1.15;letter-spacing:-.55px;margin:0 0 7px}\n.pattern-copy-v15 p{font-size:11px;line-height:1.55;color:#777;margin:0;max-width:52ch}\n/* compact mode remains intentionally dense */\n.v13-website-wall.is-compact,.v13-section-wall.is-compact{grid-template-columns:repeat(3,minmax(0,1fr));gap:16px 12px}\n@media(max-width:900px){\n  .v13-website-wall,.v13-section-wall{grid-template-columns:1fr 1fr;gap:18px 14px}\n  .patterns-hero-v15{grid-template-columns:1fr;gap:18px}\n  .patterns-grid-v15{grid-template-columns:1fr}\n}\n@media(max-width:650px){\n  .v13-site-wall,.v13-website-wall,.v13-section-wall{grid-template-columns:1fr;gap:18px}\n  .v13-site-wall>.site-tile,.v13-site-wall>.site-tile:nth-child(n){grid-column:auto!important}\n  .site-card,.module-card{padding:6px 6px 0;border-radius:13px}\n  .site-card-body,.module-card-body{padding:10px 8px 11px}\n  .patterns-page-v15{padding-top:36px;padding-bottom:70px}\n  .patterns-hero-v15 h1{font-size:46px;letter-spacing:-2.6px}\n  .patterns-grid-v15{gap:14px}\n  .pattern-pair-v15{grid-template-columns:1.1fr .9fr}\n  .pattern-card-v15{padding:8px;border-radius:13px}\n  .pattern-copy-v15{padding:12px 3px 4px}\n}\n'
if "V1.5 — tighter gallery rhythm" not in css:
    css += "\n\n"+overrides+"\n"
css_path.write_text(css)
print("Applied V1.5 gallery, sections and patterns refinement")